#!/bin/sh
# Third round: finisher and T-shirt (medal as reference), start seen from behind, pacer. Dev tool.
SP=/c/Users/jaemi/AppData/Local/Temp/claude/7e6ff043f79a9415/ab92f51c-d44a-48f8-b922-d120aba180a3/scratchpad
G=$SP/marathon/gen
STYLE="Bright contemporary sports photograph made on a modern full-frame digital camera, fast shutter so every person is sharp, low spring morning sun from the side with crisp shadows, clear pale blue sky, clean true-to-life colour and natural skin. No film grain, no haze, no motion blur, no vignette, not cinematic. Everyone wears plain unbranded running clothes in white, black, cobalt blue and a little red. No race bib numbers, no letters, no logos or brand marks on clothing or shoes, no readable signs anywhere."

python -I $SP/tools/gen_image.py --out $G/finisher.png --ref $G/medal2.jpg --aspect 4:5 --prompt "$STYLE Use exactly the medal and ribbon from the reference image. A Korean woman in her late forties who has just finished a city half marathon stands in the finish area and lifts that medal, which hangs around her neck on its blue ribbon, towards the camera with one hand, laughing, face shiny with sweat, cheeks flushed, hair tied back, plain cobalt blue running T-shirt. Behind her, softly out of focus, a few other finishers and a plain white tent. Portrait framing from the waist up, 85mm lens, eye level. Her hand and fingers natural, five fingers." > $G/finisher.log 2>&1 &

python -I $SP/tools/gen_image.py --out $G/tshirt.png --ref $G/medal2.jpg --aspect 4:5 --prompt "Same pale grey poured concrete and the same hard low morning sunlight from the upper left as in the reference photograph, but without the medal. Photographed from directly above: one neatly folded short-sleeve technical running T-shirt in vivid cobalt blue, the same blue as the reference ribbon, made of fine breathable mesh fabric, with a thin red line inside the crew collar. Folded into a neat rectangle with the collar at the top. No text, no print, no logo, no labels visible. Crisp, true colour, modern catalogue photograph, no film grain." > $G/tshirt.log 2>&1 &

python -I $SP/tools/gen_image.py --out $G/start2.png --aspect 16:9 --prompt "$STYLE Seen from behind and slightly above the crowd: hundreds of amateur Korean runners of all ages fill a wide tree-lined city avenue closed to traffic, a minute before the start of a half marathon, looking forward towards the low morning sun at the far end of the avenue; many raise their arms and cheer, some bounce on their toes. We see mostly their backs, shoulders and the backs of their heads, plain T-shirts and singlets with nothing printed on the back. Plain white crowd barriers along both sides, a couple of volunteers in plain white vests. Modern mid-rise buildings with blank facades and no signboards, young ginkgo trees in fresh leaf. Long shadows stretch toward the camera." > $G/start2.log 2>&1 &

python -I $SP/tools/gen_image.py --out $G/pacer.png --aspect 3:2 --prompt "$STYLE A pacer in a city half marathon: a lean, smiling Korean man in his fifties in a plain red running singlet, with a small plain red triangular pennant on a short flexible pole fixed to his back, running on a wide riverside levee road at an easy steady pace and looking back over his shoulder to encourage the group of eight amateur runners following close behind him. 70mm lens from the roadside at hip height, every runner mid-stride with natural running form, the calm river and fresh green trees behind." > $G/pacer.log 2>&1 &

wait
